const SESSION_COUNTER = path.join(process.env.HOME, '.openclaw', 'workspace', 'state', 'session_counter.json');

// === Session-once 鎖：每場 session 只注入一次「執行合約」===
// 教練困擾：原本每則訊息都注入 850 字合約，貼大量內容時兩三句就 context 爆炸。
// 修正：以 context-overflow-guard 的 session_counter.json 之 bootstrapTime 為 session 識別，
//       同一場 session 只在「第一次命中任務訊號」時注入一次。新 session（counter 重建）才會再注入。
function shouldInjectThisSession() {
  try {
    let bootstrapTime = null;
    if (fs.existsSync(SESSION_COUNTER)) {
      const c = JSON.parse(fs.readFileSync(SESSION_COUNTER, 'utf-8'));
      bootstrapTime = c.bootstrapTime || null;
    }
    let marker = { bootstrapTime: null, injected: false };
    if (fs.existsSync(SESSION_MARKER)) {
      marker = JSON.parse(fs.readFileSync(SESSION_MARKER, 'utf-8'));
    }
    if (marker.bootstrapTime !== bootstrapTime) {
      marker = { bootstrapTime, injected: false };
    }
    if (marker.injected) return false;
    marker.injected = true;
    const dir = path.dirname(SESSION_MARKER);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(SESSION_MARKER, JSON.stringify(marker));
    return true;
  } catch (e) {
    return true;
  }
}

